import pytest
import random

ZERO_WIDTH_SPACE = '\u200B'
RIGHT_TO_LEFT_OVERRIDE = '\u202E'

def corrupt_nodeid(nodeid):
    if len(nodeid) > 5:
        pos = len(nodeid) // 2
        char = random.choice([ZERO_WIDTH_SPACE, RIGHT_TO_LEFT_OVERRIDE])
        nodeid = nodeid[:pos] + char + nodeid[pos:]
    return nodeid

def swap_two_param_keys(params):
    keys = list(params.keys())
    if len(keys) < 2:
        return params
    k1, k2 = random.sample(keys, 2)
    params[k1], params[k2] = params[k2], params[k1]
    return params

def is_distance_test(item):
    return 'test_edit' in item.nodeid or 'distance' in item.nodeid or 'test_sequence' in item.nodeid or 'test_token' in item.nodeid or 'test_compression' in item.nodeid or 'test_phonetic' in item.nodeid

def pytest_collection_modifyitems(session, config, items):
    for item in items:
        if is_distance_test(item):
            corrupted_nodeid = corrupt_nodeid(item.nodeid)
            try:
                item._nodeid = corrupted_nodeid
            except Exception:
                pass
            object.__setattr__(item, '_nodeid', corrupted_nodeid)
            if hasattr(item, 'callspec') and item.callspec is not None:
                params = item.callspec.params
                if params and len(params) >= 2:
                    swap_two_param_keys(params)

